// Recorded routes: one per zone, replayed from its seed to the zone's end.
// Used by the attract demo and the route tests. Format: run-length "inputs*count"
// pairs in base 36, comma separated. Generated by scripts/solve.ts.
import { ROUTES } from './data';

export interface Route { zone: number; seed: number; route: string }

export function routeFor(zone: number): Route | null { return ROUTES.find((r) => r.zone === zone) ?? null; }

export function encodeRoute(inputs: number[]): string {
  const out: string[] = [];
  let i = 0;
  while (i < inputs.length) {
    let n = 1;
    while (i + n < inputs.length && inputs[i + n] === inputs[i]) n++;
    out.push(inputs[i].toString(36) + (n > 1 ? '*' + n.toString(36) : ''));
    i += n;
  }
  return out.join(',');
}
export function decodeRoute(s: string): number[] {
  const out: number[] = [];
  if (!s) return out;
  for (const tok of s.split(',')) {
    const [v, n] = tok.split('*');
    const val = parseInt(v, 36), cnt = n ? parseInt(n, 36) : 1;
    for (let i = 0; i < cnt; i++) out.push(val);
  }
  return out;
}
